import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.js';

const $=s=>document.querySelector(s), scene=new THREE.Scene();
scene.background=new THREE.Color(0xd5a66c); scene.fog=new THREE.FogExp2(0xd5a66c,.00165);
const camera=new THREE.PerspectiveCamera(48,innerWidth/innerHeight,.1,1800);
const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.18;renderer.outputColorSpace=THREE.SRGBColorSpace;$('#game').prepend(renderer.domElement);
const hemi=new THREE.HemisphereLight(0xffedce,0x806344,2.1);scene.add(hemi);const sun=new THREE.DirectionalLight(0xffdfad,3.2);sun.position.set(-180,260,100);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-230;sun.shadow.camera.right=230;sun.shadow.camera.top=230;sun.shadow.camera.bottom=-230;sun.shadow.bias=-.0002;scene.add(sun);
const mat=(color,roughness=.92)=>new THREE.MeshStandardMaterial({color,roughness});
const mats={sand:mat(0xc69b61),sand2:mat(0xb98d57),rock:mat(0x937451),road:mat(0x88704f),roadLight:mat(0xa1865f),plaster:mat(0xc9a16d),pale:mat(0xe4d2a7),dark:mat(0x553a2a),wood:mat(0x75513a),green:mat(0x667b49),water:mat(0x61aaa1,.55)};
function terrainHeight(x,z){return Math.sin(x*.014)*2.1+Math.cos(z*.017)*2.8+Math.sin((x+z)*.008)*3.1+Math.cos(Math.sqrt(x*x+z*z)*.019)*1.5;}
// Vast, gently folded highland with a naturally colored vertex surface.
const N=180,S=900,geo=new THREE.PlaneGeometry(S,S,N,N);geo.rotateX(-Math.PI/2);const pos=geo.attributes.position,colors=[];
const cA=new THREE.Color(0xc99e66),cB=new THREE.Color(0xb18a59),cC=new THREE.Color(0xd2ad78);
for(let i=0;i<pos.count;i++){const x=pos.getX(i),z=pos.getZ(i),h=terrainHeight(x,z);pos.setY(i,h);const grain=(Math.sin(x*.23+z*.18)*.025+Math.sin(z*.39)*.015);let c=cA.clone().lerp(cB,Math.max(0,Math.sin(x*.009+z*.004)*.35+.08)).lerp(cC,Math.max(0,grain));colors.push(c.r,c.g,c.b)}geo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));geo.computeVertexNormals();const ground=new THREE.Mesh(geo,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1}));ground.receiveShadow=true;scene.add(ground);
const city=new THREE.Group();scene.add(city);const placed=new THREE.Group();scene.add(placed);const interactables=[];
function addBox(parent,x,y,z,w,h,d,material,shadow=true){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);m.position.set(x,y+h/2,z);m.castShadow=shadow;m.receiveShadow=true;parent.add(m);return m;}
function addRoad(x,z,w,d,rotation=0,material=mats.road){const m=new THREE.Mesh(new THREE.BoxGeometry(w,.12,d),material);m.position.set(x,terrainHeight(x,z)+.08,z);m.rotation.y=rotation;m.receiveShadow=true;city.add(m);return m;}
// Main roads stitch the old city into a broad, legible street grid.
for(let i=-5;i<=5;i++){addRoad(i*27,0,8,340,0,i%3===0?mats.roadLight:mats.road);addRoad(0,i*27,340,8,0,mats.road)}
// Historic Sana'a-inspired tower houses, with pale decorative bands and inset windows.
function makeTower(parent,x,z,scale=1,rotation=0,variant=0){const g=new THREE.Group();g.position.set(x,terrainHeight(x,z),z);g.rotation.y=rotation;g.scale.setScalar(scale);const floors=3+Math.floor(Math.random()*3),w=6.6+Math.random()*1.7,d=6.3+Math.random()*1.3,base=variant?mats.pale:mats.plaster;
 addBox(g,0,0,0,w,.65,d,mats.wood);let y=.55;for(let f=0;f<floors;f++){const fw=w*(1-f*.035),fd=d*(1-f*.025);addBox(g,0,y,0,fw,3.05,fd,base);for(const side of [-1,1]){for(const px of [-1.6,1.6]){const win=addBox(g,px,y+1.35,side*(fd/2+.035),.8,1.15,.12,mats.dark,false);win.material=variant&&Math.random()>.5?mats.wood:mats.dark;addBox(g,px,y+2.42,side*(fd/2+.12),1.05,.17,.18,mats.pale,false);addBox(g,px,y+.55,side*(fd/2+.12),1.05,.17,.18,mats.pale,false)} }
 // bright horizontal plaster frieze, the signature silhouette of old Sana'a.
 addBox(g,0,y+2.82,0,fw+.16,.32,fd+.16,mats.pale,false);y+=3.05;}
 addBox(g,0,y,0,w+.3,.55,d+.3,mats.pale);addBox(g,0,y+.34,0,w*.62,.3,d*.62,mats.plaster);const door=addBox(g,0,.03,d/2+.07,1.1,1.9,.18,mats.wood,false);g.userData.kind='tower';parent.add(g);return g;}
// Irregular dense historic core with gardens and patchwork market roofs.
for(let gx=-8;gx<=8;gx++)for(let gz=-8;gz<=8;gz++){const x=gx*15+(Math.random()-.5)*8,z=gz*15+(Math.random()-.5)*8;if(Math.hypot(x,z)<155&&Math.random()>.22&&Math.hypot(x%27,z%27)>6)makeTower(city,x,z,.64+Math.random()*.32,Math.random()*6.28,Math.random()>.78?1:0)}
// Landmark mosque and old-city gate.
function landmark(x,z,type){const g=new THREE.Group();g.position.set(x,terrainHeight(x,z),z);city.add(g);if(type==='mosque'){addBox(g,0,0,0,22,10,19,mats.pale);addBox(g,0,10,0,25,.65,22,mats.plaster);for(let i=-1;i<=1;i++)addBox(g,i*6,10.6,0,1.2,2.2,1.2,mats.pale);for(const sx of [-1,1]){addBox(g,sx*14,0,0,3,28,3,mats.plaster);addBox(g,sx*14,28,0,4,.8,4,mats.pale);addBox(g,sx*14,18,0,4,.55,4,mats.pale)}}else{addBox(g,0,0,0,24,16,5,mats.plaster);addBox(g,0,16,0,26,.8,6,mats.pale);addBox(g,0,0,0,5,11,6,mats.dark)} }
landmark(-22,-18,'mosque');landmark(30,18,'gate');
// Oasis gardens outside the old walls.
for(let i=0;i<14;i++){const x=150+(Math.random()-.5)*100,z=90+(Math.random()-.5)*100;const green=new THREE.Mesh(new THREE.CircleGeometry(7+Math.random()*8,14),mats.green);green.rotation.x=-Math.PI/2;green.position.set(x,terrainHeight(x,z)+.07,z);city.add(green);for(let j=0;j<3;j++){const trunk=addBox(city,x+(Math.random()-.5)*8,terrainHeight(x,z)+.1,z+(Math.random()-.5)*8,.45,4,.45,mats.wood);const crown=new THREE.Mesh(new THREE.ConeGeometry(2.5,4,7),mats.green);crown.position.set(trunk.position.x,terrainHeight(x,z)+5.5,trunk.position.z);crown.castShadow=true;city.add(crown)}}
// Distant ochre mesas frame the enormous playable valley.
for(let i=0;i<22;i++){const a=i/22*Math.PI*2,r=470+Math.random()*65,x=Math.cos(a)*r,z=Math.sin(a)*r,rock=new THREE.Mesh(new THREE.ConeGeometry(40+Math.random()*40,45+Math.random()*65,5+Math.floor(Math.random()*3)),mats.rock);rock.position.set(x,terrainHeight(x,z)+22,z);rock.scale.z=.8+Math.random()*.6;rock.rotation.y=Math.random()*6;rock.receiveShadow=true;city.add(rock)}

