// Distant ochre mesas frame the enormous playable valley.
for(let i=0;i<22;i++){const a=i/22*Math.PI*2,r=470+Math.random()*65,x=Math.cos(a)*r,z=Math.sin(a)*r,rock=new THREE.Mesh(new THREE.ConeGeometry(40+Math.random()*40,45+Math.random()*65,5+Math.floor(Math.random()*3)),mats.rock);rock.position.set(x,terrainHeight(x,z)+22,z);rock.scale.z=.8+Math.random()*.6;rock.rotation.y=Math.random()*6;rock.receiveShadow=true;city.add(rock)}

const options=[
 {id:'house',name:'Дім',icon:'🏠',cost:120,builder:g=>makeTower(g,0,0,.65)},
 {id:'tower',name:'Вежа',icon:'🏛️',cost:260,builder:g=>makeTower(g,0,0,1.05,0,1)},
 {id:'market',name:'Базар',icon:'🧺',cost:190,builder:g=>{addBox(g,0,0,0,13,.5,10,mats.wood);for(let i=-1;i<=1;i++){addBox(g,i*4,2.1,0,3.8,3.2,3,mats.plaster);addBox(g,i*4,4,0,4,.3,3.3,mats.pale)}addBox(g,0,3.9,0,13,.35,11,mats.wood)}},
 {id:'mosque',name:'Мечеть',icon:'🕌',cost:440,builder:g=>{addBox(g,0,0,0,14,7,12,mats.pale);addBox(g,0,7,0,16,.6,14,mats.plaster);for(const s of [-1,1]){addBox(g,s*9,0,0,2.2,17,2.2,mats.plaster);addBox(g,s*9,17,0,3,.6,3,mats.pale)}addBox(g,0,7.3,0,2,2,2,mats.pale)}},
 {id:'garden',name:'Оазис',icon:'🌴',cost:85,builder:g=>{const p=new THREE.Mesh(new THREE.CircleGeometry(5,16),mats.green);p.rotation.x=-Math.PI/2;p.position.y=.12;g.add(p);for(let i=0;i<3;i++){const a=i*2.094,x=Math.cos(a)*2,z=Math.sin(a)*2;addBox(g,x,.1,z,.35,3.2,.35,mats.wood);const c=new THREE.Mesh(new THREE.ConeGeometry(1.6,2.8,7),mats.green);c.position.set(x,4,z);g.add(c)}}},
 {id:'well',name:'Криниця',icon:'🪣',cost:70,builder:g=>{const ring=new THREE.Mesh(new THREE.CylinderGeometry(2,2.3,1.2,12),mats.pale);ring.position.y=.65;g.add(ring);const water=new THREE.Mesh(new THREE.CylinderGeometry(1.5,1.5,.1,12),mats.water);water.position.y=1.28;g.add(water);addBox(g,0,2.8,0,.4,3.4,.4,mats.wood);addBox(g,0,4.4,0,2.3,.25,.3,mats.wood)}},
 {id:'road',name:'Дорога',icon:'🛣️',cost:18,builder:g=>{const r=new THREE.Mesh(new THREE.BoxGeometry(10,.12,7),mats.road);r.position.y=.08;g.add(r)}}
];let selected='house',rotation=0,money=12500,population=1240,buildings=[],ghost=null,ghostValid=false,hoverPoint=null;
function makeBuilding(type,x,z,rot=0,save=true){const opt=options.find(o=>o.id===type);if(!opt)return;const g=new THREE.Group();opt.builder(g);g.position.set(x,terrainHeight(x,z)+.12,z);g.rotation.y=rot;g.userData={type,placed:true};placed.add(g);buildings.push({type,x,z,rot,group:g});if(save)persist();return g;}
function pickOption(id){selected=id;document.querySelectorAll('.tool').forEach(t=>t.classList.toggle('active',t.dataset.id===id));if(ghost)scene.remove(ghost);ghost=new THREE.Group();options.find(o=>o.id===id).builder(ghost);ghost.traverse(o=>{if(o.isMesh){o.castShadow=false;o.material=o.material.clone();o.material.transparent=true;o.material.opacity=.48;o.material.depthWrite=false;o.material.emissive=new THREE.Color(0x443020)}});scene.add(ghost);}
const tools=$('#tools');for(const opt of options){const b=document.createElement('button');b.className='tool';b.dataset.id=opt.id;b.innerHTML=`<span class="emoji">${opt.icon}</span><small>${opt.name}</small><span class="cost">${opt.cost} ﷼</span>`;b.onclick=()=>pickOption(opt.id);tools.append(b)}pickOption(selected);
const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2();let aim=new THREE.Vector3();function aimAt(e){const r=renderer.domElement.getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-((e.clientY-r.top)/r.height)*2+1);raycaster.setFromCamera(pointer,camera);const hit=raycaster.intersectObject(ground,false)[0];if(hit){const x=Math.round(hit.point.x/2)*2,z=Math.round(hit.point.z/2)*2;if(Math.abs(x)<425&&Math.abs(z)<425){aim.set(x,terrainHeight(x,z),z);hoverPoint={x,z};if(ghost){ghost.position.set(x,aim.y+.12,z);ghost.rotation.y=rotation;ghostValid=true}}else{hoverPoint=null;ghostValid=false}}else{hoverPoint=null;ghostValid=false}}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2100)}
function place(){if(!hoverPoint)return;if($('#bulldoze').classList.contains('active')){let closest=null,dist=14;for(const b of buildings){const d=Math.hypot(b.x-hoverPoint.x,b.z-hoverPoint.z);if(d<dist){dist=d;closest=b}}if(closest){placed.remove(closest.group);buildings=buildings.filter(b=>b!==closest);money+=Math.round((options.find(o=>o.id===closest.type)?.cost||0)*.45);population=Math.max(1240,population-12);refreshStats();persist();toast('Споруду знесено · частину коштів повернуто')}else toast('Поруч немає споруд');return}
 const opt=options.find(o=>o.id===selected);if(money<opt.cost){toast('Недостатньо ріалів для будівництва');return}if(Math.abs(hoverPoint.x)>410||Math.abs(hoverPoint.z)>410){toast('Це вже край долини');return}money-=opt.cost;makeBuilding(selected,hoverPoint.x,hoverPoint.z,rotation);if(selected!=='road')population+=selected==='tower'?18:selected==='house'?12:selected==='market'?5:0;refreshStats();toast(`${opt.name} збудовано!`)}
function refreshStats(){$('#money').textContent=money.toLocaleString('uk-UA');$('#population').textContent=population.toLocaleString('uk-UA');$('#buildingCount').textContent=buildings.length}
function persist(){try{localStorage.setItem('sanaa-city-save',JSON.stringify({money,population,buildings:buildings.map(({type,x,z,rot})=>({type,x,z,rot}))}))}catch{}}
function load(){try{const d=JSON.parse(localStorage.getItem('sanaa-city-save')||'null');if(d){money=d.money??money;population=d.population??population;for(const b of d.buildings||[])makeBuilding(b.type,b.x,b.z,b.rot,false)}}catch{}refreshStats()}load();

