function load(){try{const d=JSON.parse(localStorage.getItem('sanaa-city-save')||'null');if(d){money=d.money??money;population=d.population??population;for(const b of d.buildings||[])makeBuilding(b.type,b.x,b.z,b.rot,false)}}catch{}refreshStats();}

let target=new THREE.Vector3(0,0,0),yaw=.72,pitch=.78,distance=285;const keys=new Set();let dragging=false,lastX=0,lastY=0,downX=0,downY=0,moved=0;
function updateCamera(){pitch=THREE.MathUtils.clamp(pitch,.22,1.35);const cp=Math.cos(pitch);camera.position.set(target.x+Math.sin(yaw)*distance*cp,target.y+Math.sin(pitch)*distance,target.z+Math.cos(yaw)*distance*cp);camera.lookAt(target)}updateCamera();
